processFileJob.body:
{
	// Hash the file contents (currently defaults to SHA1)
	hashStr, err := dc.hashFile(job.path)
	if err != nil {
		return nil, 0, nil, fmt.Errorf("failed to hash file %s: %w", job.path, err)
	}

	// Convert hash string to bytes
	hashBytes, err := hex.DecodeString(hashStr)
	if err != nil {
		return nil, 0, nil, fmt.Errorf("invalid hash %s: %w", hashStr, err)
	}

	// Currently using SHA1 - TODO: make configurable
	hashType := HashTypeSHA1

	// Get system-specific file information
	stat := job.info.Sys().(*syscall.Stat_t)

	return hashBytes, hashType, stat, nil
}

hashFile.body:
{
	file, err := os.Open(filePath)
	if err != nil {
		return "", fmt.Errorf("failed to open file %s: %w", filePath, err)
	}
	defer file.Close()

	hasher := sha1.New()
	if _, err := io.Copy(hasher, file); err != nil {
		return "", fmt.Errorf("failed to hash file %s: %w", filePath, err)
	}

	return hex.EncodeToString(hasher.Sum(nil)), nil
}

ParseDebugFlags.body:
{
	if debugStr == "" {
		return
	}

	options := strings.Split(debugStr, ",")
	for _, option := range options {
		option = strings.TrimSpace(option)
		if option == "" {
			continue
		}

		// Handle option:value format
		parts := strings.SplitN(option, ":", 2)
		optionName := strings.ToLower(parts[0])
		optionValue := "true"
		if len(parts) > 1 {
			optionValue = parts[1]
		}

		switch optionName {
		case "extravalidation":
			debugFlags.extraValidation = parseBoolOption(optionValue)
		case "memorylayout":
			debugFlags.memoryLayout = parseBoolOption(optionValue)
		case "indexchaining":
			debugFlags.indexChaining = parseBoolOption(optionValue)
		case "scanning":
			debugFlags.scanning = parseBoolOption(optionValue)
		}
	}
}

parseBoolOption.body:
{
	switch strings.ToLower(value) {
